CREATE POLICY "Signed in users can view item photos" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'item-images');
CREATE POLICY "Users can upload their own item photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'item-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users can update their own item photos" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'item-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users can delete their own item photos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'item-images' AND (storage.foldername(name))[1] = auth.uid()::text);